INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (1,1,1,201,1,'2026-05-05 09:15:00','Hipertensa há 5 anos, em uso de losartana 50mg/dia. Refere sedentarismo parcial.','Cefaleia leve e necessidade de revisão de medicação.','PA 148x92 mmHg, FC 78 bpm, sem sinais de alarme.','Hipertensão arterial sistêmica sem controle ideal.','Reforçadas medidas não farmacológicas e aumento de seguimento. Mantida losartana e solicitado MAPA se persistência.','Paciente compreendeu orientação e retornará em 15 dias.','Preferir consultas pela manhã.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (2,1,2,201,2,'2026-05-06 10:10:00','DM2 em uso irregular de metformina. Dieta com alto teor de carboidrato.','Cansaço, sede aumentada e oscilação glicêmica.','IMC 31, glicemia capilar 212 mg/dL.','Diabetes mellitus tipo 2 descompensado.','Solicitados exames laboratoriais completos, reforço dietético e retorno em 7 dias.','Motivado a aderir melhor ao tratamento.','Necessita acompanhamento multiprofissional.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (3,1,3,201,3,'2026-05-07 15:10:00','Histórico de rinite alérgica e sinusite de repetição.','Congestão nasal residual após tratamento.','Sem febre, saturação normal, fala em frases completas.','Sinusite aguda em melhora clínica.','Manter lavagem nasal, hidratação e finalizar medicação prescrita anteriormente.','Boa resposta terapêutica; liberada para atividades habituais.','Teleconsulta concluída sem intercorrências.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (4,1,5,202,5,'2026-05-08 14:10:00','Paciente sem comorbidades, escovação 2x ao dia, uso irregular de fio dental.','Sensibilidade em molar superior direito.','Lesão de cárie em elemento 16, biofilme supragengival leve.','Cárie dentária em esmalte/dentina no elemento 16.','Indicada restauração em resina, orientação de higiene e profilaxia.','Paciente aceitou plano de tratamento proposto.','Solicitada radiografia bite-wing se sensibilidade persistir.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5,1,4,201,4,'2026-05-12 08:50:00','Dislipidemia em uso de sinvastatina 20mg. Sem dor torácica.','Retorno com exames de rotina.','PA 128x80 mmHg, LDL ainda acima da meta.','Dislipidemia mista com resposta parcial ao tratamento.','Ajustado tratamento e mantido acompanhamento trimestral.','Evolução estável.','Reforçada adesão à dieta e caminhada.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (6,1,7,202,7,'2026-05-17 09:20:00','Paciente pediátrica com rinite alérgica, boa colaboração em consultório.','Consulta preventiva odontológica.','Placa bacteriana leve e inflamação gengival discreta.','Gengivite leve associada à higiene insuficiente.','Profilaxia, aplicação tópica de flúor e reforço educativo para responsável.','Sem dor, procedimento bem tolerado.','Retorno preventivo em 6 meses.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5001,1,2001,201,4001,'2026-05-12 09:10:00','Paciente comparece para check-up anual, refere sedentarismo parcial e controle irregular da pressão.','Deseja avaliação geral, revisão de exames e ajuste de hábitos.','Bom estado geral, hidratado, PA 138x86 mmHg, FC 78 bpm, ausculta cardíaca e pulmonar sem alterações relevantes.','Hipertensão estágio 1 em acompanhamento; sobrepeso; dislipidemia em investigação.','Solicitados exames laboratoriais, reforço de dieta hipossódica e atividade física regular.','Paciente orientado e concordante com mudanças de estilo de vida.','Retorno em 30 dias com exames.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5002,1,2002,202,4002,'2026-05-12 10:10:00','Paciente relata sangramento gengival esporádico e sensibilidade em molar superior direito.','Avaliação odontológica inicial e limpeza.','Biofilme moderado, gengivite leve e restauração antiga infiltrada em 16.','Gengivite associada a biofilme e suspeita de infiltração em restauração.','Profilaxia, orientação de higiene, radiografia interproximal e planejamento restaurador.','Boa compreensão e adesão às orientações.','Retorno para restauração e reavaliação periodontal.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5003,1,2003,203,4003,'2026-05-12 11:05:00','Paciente em seguimento psicológico por ansiedade, preocupação excessiva e perfeccionismo no trabalho.','Ansiedade, autocobrança e ruminação.','Sem exame físico aplicável; apresentação compatível com bom autocuidado.','Sintomas ansiosos com prejuízo leve a moderado no funcionamento ocupacional.','Psicoeducação, identificação de gatilhos e treino inicial de respiração diafragmática.','Paciente engajada, verbaliza alívio após reestruturação cognitiva inicial.','Manter registro de pensamentos automáticos.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5004,1,2004,204,4004,'2026-05-12 13:05:00','Paciente com histórico de humor deprimido, insônia terminal e queda de energia há cerca de 5 meses.','Humor deprimido, irritabilidade e insônia.','Estado geral preservado, sem alterações neurológicas focais observáveis na consulta.','Episódio depressivo em investigação; transtorno ansioso associado.','Ajuste de antidepressivo, orientação de higiene do sono e avaliação de risco.','Paciente consciente, crítico, sem sinais psicóticos no momento.','Retorno em 15 dias.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5005,1,2005,205,4005,'2026-05-12 14:05:00','Mãe refere febre há 2 dias, coriza e tosse seca, com redução leve do apetite.','Febre e sintomas respiratórios altos.','Afebril no momento após antitérmico, orofaringe hiperemiada leve, ausculta pulmonar sem ruídos adventícios.','Infecção viral de vias aéreas superiores.','Medidas de suporte, hidratação, controle térmico e sinais de alarme.','Criança ativa, hidratada e sem desconforto respiratório.','Retorno se persistência da febre ou piora clínica.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5006,1,2006,206,4006,'2026-05-12 15:05:00','Gestante G2P1A0, 24 semanas, sem queixas relevantes, boa aceitação alimentar e movimentação fetal presente.','Retorno de pré-natal.','PA 110x70 mmHg, peso adequado para a idade gestacional, BCF presente, sem edema.','Gestação de baixo risco em evolução habitual.','Manter suplementação, solicitar exames de rotina do trimestre e reforçar sinais de alerta.','Paciente orientada e tranquila.','Retorno em 4 semanas.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5007,1,2007,207,4007,'2026-05-12 16:05:00','Dor em joelho direito há 3 semanas, piora ao correr e subir escadas, sem trauma direto importante.','Dor no joelho direito.','Dor à palpação patelofemoral, sem derrame importante, arco preservado com desconforto no agachamento.','Síndrome dolorosa femoropatelar; tendinopatia associada a sobrecarga.','Analgesia, redução temporária do impacto e encaminhamento para fisioterapia.','Paciente entende necessidade de ajuste do treino.','Retorno em 21 dias.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5008,1,2008,208,4008,'2026-05-13 09:05:00','Paciente hipertensa, com palpitações episódicas e dispneia aos médios esforços.','Palpitações e avaliação de risco cardiovascular.','PA 146x88 mmHg, FC 84 bpm, sem edema, bulhas normofonéticas.','Hipertensão arterial sistêmica; palpitações em investigação; risco CV intermediário/alto.','Solicitados ECG, ecocardiograma e Holter; ajuste de antihipertensivo e metas pressóricas.','Paciente compreende necessidade de estratificação.','Retorno com exames.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5009,1,2009,209,4009,'2026-05-13 10:05:00','Paciente com baixa visual progressiva e dificuldade para leitura noturna, nega trauma ocular.','Visão embaçada e cansaço visual.','Sem hiperemia importante; acuidade reduzida sem correção em ambos os olhos.','Erro refracional associado a suspeita de catarata inicial.','Atualização de refração, orientação e solicitação de exames complementares.','Paciente orientado sobre acompanhamento seriado.','Revisão após exames e adaptação de correção óptica.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5010,1,2010,210,4010,'2026-05-13 11:05:00','Paciente refere cefaleia pulsátil recorrente, parestesias transitórias em membro superior esquerdo e fotofobia.','Cefaleia e parestesias.','Sem déficit focal fixo na consulta, marcha preservada, fala sem alterações.','Enxaqueca com aura em investigação diferencial; necessidade de exclusão de outras causas neurológicas.','Solicitada RM de crânio, ajuste de profilaxia e diário de cefaleia.','Paciente sem sinais de alarme no momento.','Retorno em 30 dias ou antes se piora.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5011,1,2011,201,4011,'2026-07-01 09:00:10','Paciente em consulta de seguimento preventivo, com revisão de hábitos, rotina de exames e fatores de risco metabólico.','Deseja avaliação clínica geral e orientação de prevenção.','Bom estado geral, sinais vitais estáveis e sem alterações agudas relevantes ao exame físico.','Acompanhamento preventivo; necessidade de reforço em hábitos de vida e controle laboratorial.','Solicitados exames de rotina, reforçadas orientações sobre alimentação, sono e atividade física.','Paciente aderente e concordante com retorno programado.','Retorno com exames em prazo habitual.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5012,1,2013,202,4014,'2026-07-01 10:00:10','Paciente refere sensibilidade localizada e interesse em revisão odontológica preventiva.','Sensibilidade dentária e necessidade de avaliação bucal.','Biofilme leve a moderado, restaurações prévias íntegras exceto ponto suspeito em molar.','Cárie inicial / necessidade de acompanhamento periodontal preventivo.','Orientação de higiene, profilaxia e planejamento restaurador conforme exame clínico.','Boa aceitação do plano terapêutico proposto.','Agendado retorno para execução e reavaliação.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5013,1,2015,203,4017,'2026-07-02 11:00:10','Paciente busca atendimento por sobrecarga emocional, ansiedade e dificuldade de organização da rotina.','Ansiedade, estresse e autocobrança.','Apresentação adequada, discurso coerente e contato preservado.','Sintomas ansiosos com impacto funcional leve a moderado.','Psicoeducação, acolhimento, identificação de gatilhos e proposta de acompanhamento.','Paciente engajado e disposto a manter registro entre sessões.','Manter seguimento semanal e tarefas entre sessões.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5014,1,2017,204,4020,'2026-07-02 13:30:10','Paciente em avaliação por humor deprimido, insônia e oscilação de energia nas últimas semanas.','Humor deprimido, ansiedade e sono não reparador.','Estado mental sem sinais psicóticos, crítica preservada e sem risco agudo identificado.','Transtorno ansioso/depressivo em investigação e seguimento.','Ajuste terapêutico inicial, higiene do sono e orientação sobre sinais de alerta.','Paciente compreende plano e aceita acompanhamento próximo.','Retorno breve para reavaliação de resposta clínica.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5015,1,2019,205,4023,'2026-07-03 14:30:10','Consulta de puericultura/seguimento, com revisão de crescimento, alimentação e marcos de desenvolvimento.','Rotina pediátrica e orientações preventivas.','Criança ativa, hidratada, sem sinais de toxemia ou desconforto respiratório.','Seguimento pediátrico sem intercorrências maiores no momento.','Orientações de sono, alimentação, vacinação e sinais de alerta aos responsáveis.','Responsável orientado e sem dúvidas ao final da consulta.','Programado retorno conforme faixa etária ou antes se necessidade.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5016,1,2021,206,4026,'2026-07-03 15:30:10','Paciente comparece para rotina ginecológica / seguimento com foco em prevenção e sintomas do ciclo.','Avaliação ginecológica preventiva.','Sem alterações agudas; exame clínico compatível com seguimento ambulatorial.','Seguimento ginecológico habitual; rastreio e acompanhamento conforme faixa etária.','Solicitados exames preventivos e reforçadas orientações sobre sinais de alerta.','Paciente acolhida, esclarecida e concordante com conduta.','Retorno programado após exames ou conforme necessidade clínica.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5017,1,2023,207,4029,'2026-07-04 09:00:10','Paciente com dor osteomuscular relacionada a esforço repetitivo / atividade física.','Dor articular e limitação funcional leve.','Dor à mobilização específica, sem sinais inflamatórios sistêmicos ou déficit neurovascular.','Síndrome dolorosa musculoesquelética por sobrecarga / inflamação local.','Analgesia, orientação funcional, ajuste de carga e encaminhamento para fisioterapia se indicado.','Paciente compreende medidas de proteção e retorno programado.','Monitorar resposta clínica e necessidade de imagem complementar.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5018,1,2025,208,4032,'2026-07-04 10:00:10','Paciente em reavaliação cardiológica por controle pressórico, dispneia ou palpitações intermitentes.','Controle cardiovascular e revisão de risco.','PA em faixa limítrofe, ausculta sem achados agudos e sem edema periférico.','Risco cardiovascular em seguimento, com necessidade de rastreio complementar conforme quadro.','Reforçadas metas pressóricas, atividade física e solicitação de exames complementares.','Paciente aderente e motivado a manter acompanhamento.','Retorno com monitorização e exames programados.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5019,1,2027,209,4035,'2026-07-05 11:00:10','Paciente refere cansaço visual, olho seco ou dificuldade progressiva para leitura.','Baixa visual / desconforto ocular.','Acuidade reduzida sem correção; segmento anterior sem intercorrências agudas.','Erro refracional / superfície ocular em avaliação, com seguimento ambulatorial.','Orientada refração, lubrificação ocular e complementação diagnóstica quando indicada.','Paciente orientado sobre acompanhamento seriado.','Retorno após exames e adaptação de conduta óptica.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `prontuarios` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`agendamento_id`,`data_atendimento`,`anamnese`,`queixa_principal`,`exame_fisico`,`hipotese_diagnostica`,`conduta`,`evolucao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (5020,1,2029,210,4038,'2026-07-05 14:00:10','Paciente em investigação de cefaleia, tonturas ou parestesias transitórias sem sinais de alarme atuais.','Cefaleia recorrente / sintomas neurológicos intermitentes.','Sem déficit focal fixo ao exame clínico nesta consulta.','Cefaleia primária / quadro neurológico em investigação diferencial.','Solicitados exames conforme quadro, diário de sintomas e orientação sobre sinais de urgência.','Paciente compreende necessidade de monitorização e retorno.','Revisão com exames e avaliação de resposta terapêutica.','2026-11-11 23:52:12','2026-11-11 23:52:12');
