INSERT INTO `planos_cuidado` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`tema`,`titulo`,`objetivo`,`metas`,`conduta`,`frequencia_retorno`,`proxima_revisao`,`status`,`indicadores`,`orientacoes`,`criado_em`,`atualizado_em`) VALUES (7402,1,2006,206,'ginecologia_obstetricia','Plano de cuidado pré-natal habitual','Manter gestação de baixo risco com seguimento adequado.','- Realizar exames do trimestre\n- Acompanhar ganho ponderal\n- Revisar sinais de alerta obstétricos','Consultas periódicas, suplementação e educação em saúde.','mensal','2026-06-09','ativo','PA, BCF, peso materno, exames laboratoriais','Retornar antes em caso de sangramento, redução de movimentos fetais ou cefaleia persistente.','2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `planos_cuidado` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`tema`,`titulo`,`objetivo`,`metas`,`conduta`,`frequencia_retorno`,`proxima_revisao`,`status`,`indicadores`,`orientacoes`,`criado_em`,`atualizado_em`) VALUES (7403,1,2008,208,'cardiologia','Controle pressórico e investigação de palpitações','Melhorar controle da pressão arterial e concluir estratificação cardiovascular.','- Monitorar PA domiciliar\n- Realizar ECG, eco e Holter\n- Reforçar adesão ao tratamento','Ajuste antihipertensivo, exame complementar e revisão de estilo de vida.','30 dias','2026-06-12','ativo','PA média, FC, sintomas de palpitação, exames realizados','Evitar automedicação e procurar atendimento se dor torácica ou dispneia importante.','2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `planos_cuidado` (`id`,`empresa_id`,`paciente_id`,`profissional_id`,`tema`,`titulo`,`objetivo`,`metas`,`conduta`,`frequencia_retorno`,`proxima_revisao`,`status`,`indicadores`,`orientacoes`,`criado_em`,`atualizado_em`) VALUES (7404,1,2010,210,'neurologia','Seguimento de cefaleia com aura','Reduzir frequência das crises e excluir causas secundárias.','- Preencher diário de cefaleia\n- Realizar RM de crânio\n- Revisar resposta ao tratamento','Profilaxia medicamentosa, educação sobre gatilhos e revisão com exames.','30 dias','2026-06-12','ativo','Frequência das crises, intensidade, sintomas neurológicos associados','Procurar urgência se ocorrer déficit focal persistente ou alteração do nível de consciência.','2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `psicologia_planos` (`id`,`empresa_id`,`prontuario_id`,`paciente_id`,`profissional_id`,`abordagem`,`demanda_focal`,`objetivo_principal`,`metas`,`metas_curto_prazo`,`metas_medio_prazo`,`metas_longo_prazo`,`estrategias_intervencao`,`indicadores_evolucao`,`criterios_alta`,`risco_monitorado`,`frequencia_sugerida`,`status`,`data_inicio`,`data_reavaliacao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (1,1,NULL,3,203,'TCC',NULL,'Reduzir sintomas ansiosos e melhorar organização emocional.','Mapear gatilhos, construir rotina de regulação emocional e reforçar autocuidado.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'semanal','ativo','2026-05-10','2026-06-10','Paciente prefere encontros híbridos e acompanha exercícios entre sessões.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `psicologia_planos` (`id`,`empresa_id`,`prontuario_id`,`paciente_id`,`profissional_id`,`abordagem`,`demanda_focal`,`objetivo_principal`,`metas`,`metas_curto_prazo`,`metas_medio_prazo`,`metas_longo_prazo`,`estrategias_intervencao`,`indicadores_evolucao`,`criterios_alta`,`risco_monitorado`,`frequencia_sugerida`,`status`,`data_inicio`,`data_reavaliacao`,`observacoes`,`criado_em`,`atualizado_em`) VALUES (6201,1,5003,2003,203,'Terapia Cognitivo-Comportamental','Ansiedade de desempenho, perfeccionismo e ruminação.','Reduzir sintomas ansiosos e ampliar flexibilidade cognitiva.','Psicoeducação, manejo fisiológico da ansiedade, reestruturação cognitiva e treino de limites.','Identificar gatilhos e registrar pensamentos automáticos por 4 semanas.','Diminuir episódios de ansiedade intensa no trabalho e aumentar uso de técnicas de regulação.','Desenvolver rotina sustentável com menor autocobrança e melhor qualidade de vida.','Sessões semanais, tarefas entre sessões, registros cognitivos e experimentos comportamentais.','Redução de ruminação, melhora do sono, autoavaliação de ansiedade e adesão às tarefas.','Sintomas controlados, autonomia em estratégias de enfrentamento e melhora funcional sustentada.','Baixo risco, sem ideação atual; manter rastreio periódico.','Semanal','ativo','2026-05-12','2026-06-23','Plano terapêutico inicial com reavaliação em seis semanas.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `psicologia_prontuario` (`id`,`empresa_id`,`prontuario_id`,`paciente_id`,`profissional_id`,`tipo_registro`,`demanda_principal`,`historico_pessoal`,`historico_familiar`,`historico_psiquiatrico`,`uso_medicacao`,`fatores_risco`,`fatores_protecao`,`objetivo_terapeutico`,`queixa_historico`,`expectativas_tratamento`,`encaminhado_por`,`motivo_encaminhamento`,`historico_saude`,`uso_substancias`,`sono_apetite`,`suporte_rede`,`contexto_escolar_profissional`,`antecedentes_trauma_luto`,`humor_afeto`,`pensamento_linguagem`,`comportamento`,`cognicao_orientacao`,`estado_mental_aparencia`,`estado_mental_sensopercepcao`,`risco_suicida`,`risco_autoheteroagressao`,`temas_sessao`,`intervencoes_realizadas`,`tecnicas_utilizadas`,`resposta_paciente`,`adesao_processo`,`recursos_mobilizados`,`manejo_crise`,`tarefas_entre_sessoes`,`encaminhamentos`,`plano_sessao_seguinte`,`observacoes_confidenciais`,`consentimento_tipo`,`consentimento_terapia_texto`,`consentimento_tele_texto`,`consentimento_privacidade_texto`,`consentimento_compartilhamento_texto`,`consentimento_gravacao_texto`,`consentimento_terapia_aceito`,`consentimento_tele_aceito`,`consentimento_privacidade_aceito`,`consentimento_compartilhamento_aceito`,`consentimento_gravacao_aceito`,`consentimento_nome_responsavel`,`consentimento_documento`,`consentimento_parentesco`,`consentimento_testemunha`,`consentimento_registrado_em`,`criado_em`,`atualizado_em`) VALUES (6101,1,5003,2003,203,'sessao','Ansiedade associada à autocobrança e medo de falhar no ambiente de trabalho.','Refere histórico de perfeccionismo desde adolescência e dificuldade em dizer não.','Mãe com traços ansiosos e dinâmica familiar rígida quanto a desempenho.','Acompanhamento psiquiátrico ambulatorial sem internações prévias.','Sertralina 50mg/dia.','Sobrecarga profissional, privação de sono em períodos de fechamento e autocrítica elevada.','Rede de apoio familiar e boa capacidade reflexiva.','Reduzir intensidade da ansiedade e ampliar repertório de enfrentamento.','Queixas iniciadas com intensificação das demandas no trabalho nos últimos 12 meses.','Deseja aprender a controlar a ansiedade e melhorar equilíbrio vida-trabalho.','Demanda espontânea','Busca por manejo de ansiedade e autocobrança.','Sem comorbidades clínicas relevantes relatadas.','Uso social de álcool; nega outras substâncias.','Sono irregular em semanas mais estressantes; apetite preservado.','Boa relação com irmã e amigos próximos.','Trabalho com metas agressivas e dificuldade em pausas.','Relata término afetivo importante há 2 anos ainda com impacto emocional residual.','Ansiosa, porém com afeto congruente e acesso emocional preservado.','Curso do pensamento organizado, linguagem clara e objetiva.','Cooperativa, atenta e participativa.','Orientada em tempo, espaço e pessoa.','Boa higiene e vestimenta adequada.','Sem alterações sensoperceptivas relatadas.','baixo','Nega ideação atual e história de auto/heteroagressão.','Ansiedade de desempenho, limites pessoais, rotina de descanso.','Psicoeducação, identificação de pensamentos automáticos e validação emocional.','Reestruturação cognitiva inicial e respiração diafragmática.','Refere alívio e maior clareza sobre gatilhos.','Boa adesão.','Escrita terapêutica e apoio de rede social.','Não aplicável.','Registrar situações de ansiedade e pensamentos automáticos.','Sem encaminhamentos externos neste momento.','Aprofundar crenças centrais relacionadas a desempenho.','Sem observações confidenciais adicionais.','ambos','Paciente orientada sobre objetivos, sigilo e limites do acompanhamento psicológico.','Paciente ciente das orientações para atendimentos remotos quando necessários.','Paciente informada sobre tratamento de dados pessoais e sensíveis para fins assistenciais.','Paciente autoriza compartilhamento apenas quando clinicamente necessário e com respaldo ético/legal.','Gravações somente mediante autorização específica.',1,1,1,1,0,'Paula Mendes Souza','123.456.789-03','Própria paciente','Administrador Demo','2026-05-12 11:00:00','2026-11-11 23:52:12','2026-11-11 23:52:12');
