INSERT INTO `psiquiatria_prontuario` (`id`,`empresa_id`,`prontuario_id`,`paciente_id`,`profissional_id`,`psiq_tipo_atendimento`,`psiq_queixa_principal`,`psiq_inicio_sintomas`,`psiq_fatores_desencadeantes`,`psiq_historico_psiquiatrico`,`psiq_internacoes_previas`,`psiq_historico_familiar`,`psiq_uso_substancias`,`psiq_comorbidades`,`psiq_humor_afeto`,`psiq_pensamento`,`psiq_percepcao`,`psiq_cognicao`,`psiq_juizo_critica`,`psiq_risco_suicidio`,`psiq_plano_seguranca`,`psiq_risco_heteroagressao`,`psiq_hipotese_diag`,`psiq_cid10`,`psiq_medicacoes`,`psiq_orientacoes_efeitos`,`psiq_psicoterapia_indicada`,`psiq_encaminhamentos`,`psiq_conduta_urgente`,`psiq_plano_retorno`,`criado_em`,`atualizado_em`) VALUES (6401,1,5004,2004,204,'retorno','Humor deprimido, insônia e irritabilidade.','Há cerca de 5 meses, com piora progressiva.','Sobrecarga ocupacional e conflitos familiares recentes.','Acompanhamento ambulatorial prévio sem internações e sem episódios psicóticos.','Nega internações psiquiátricas prévias.','Tio com transtorno bipolar; mãe com ansiedade.','Uso social de álcool; nega outras substâncias.','Insônia e sintomas ansiosos associados.','Humor deprimido, afeto rebaixado, reativo em alguns momentos.','Curso do pensamento organizado, conteúdo com preocupação excessiva, sem delírios.','Nega alucinações.','Atenção e memória preservadas na consulta.','Crítica parcialmente preservada com boa adesão potencial.','baixo','Orientado a procurar suporte familiar, serviço de urgência e contato emergencial se piora importante ou ideação suicida.','Nega heteroagressividade.','Episódio depressivo com sintomas ansiosos associados.','F32.1','Escitalopram 10mg/noite, com possibilidade de ajuste gradual.','Orientado sobre latência terapêutica, náusea inicial, sonolência e importância de não interromper abruptamente.','sim','Manter seguimento psicológico concomitante.','Sem indicação de internação ou manejo urgente nesta consulta.','Retorno em 15 dias para reavaliação de resposta e tolerabilidade.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `pediatria_prontuario` (`id`,`empresa_id`,`prontuario_id`,`paciente_id`,`profissional_id`,`ped_responsavel_nome`,`ped_responsavel_parentesco`,`ped_queixa_principal`,`ped_inicio_quadro`,`ped_febre`,`ped_tempo_febre`,`ped_sintomas_associados`,`ped_contato_doentes`,`ped_peso_atual`,`ped_altura_atual`,`ped_perimetro_cefalico`,`ped_curva_crescimento`,`ped_desenvolvimento_neuropsicomotor`,`ped_aleitamento`,`ped_vacinacao_em_dia`,`ped_vacinas_pendentes`,`ped_alergias`,`ped_medicacoes_uso`,`ped_temperatura`,`ped_fc`,`ped_fr`,`ped_saturacao`,`ped_exame_fisico`,`ped_hipotese_diag`,`ped_conduta`,`ped_sinais_alarme`,`ped_retorno`,`criado_em`,`atualizado_em`) VALUES (6501,1,5005,2005,205,'Camila Martins Ferreira','Mãe','Febre e coriza há 2 dias.','Início há 48 horas.','sim','2 dias','Tosse seca, obstrução nasal e leve hiporexia.','Contato com colegas gripados na escola.','15.20','96.00','50.00','adequado','Marcos do desenvolvimento adequados para a idade.','Alimentação já diversificada, sem aleitamento materno atual.','incompleta','Reforço de influenza pendente conforme calendário relatado pela mãe.','Alergia a amoxicilina.','Antitérmico se necessário.','37.8',108,24,98,'Bom estado geral, hidratado, sem tiragem, orofaringe discretamente hiperemiada e ausculta pulmonar sem ruídos adventícios.','Infecção viral de vias aéreas superiores.','Suporte clínico, hidratação, lavagem nasal e observação domiciliar.','Procurar serviço imediatamente se desconforto respiratório, prostração, febre persistente ou recusa alimentar importante.','2026-05-15','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `ginecologia_obstetricia_prontuario` (`id`,`empresa_id`,`prontuario_id`,`paciente_id`,`profissional_id`,`go_tipo_atendimento`,`go_queixa_principal`,`go_dum`,`go_gpa`,`go_idade_gestacional`,`go_dpp`,`go_ciclo_menstrual`,`go_contracepcao`,`go_sangramento`,`go_patologias_previas`,`go_cirurgias_previas`,`go_ist_risco`,`go_ultimo_papanicolau`,`go_ultima_mamografia`,`go_pre_natal_risco`,`go_movimentos_fetais`,`go_sinais_alarme`,`go_pa`,`go_peso`,`go_bcf`,`go_altura_uterina`,`go_exame_fisico`,`go_exames_solicitados`,`go_hipotese_diag`,`go_conduta`,`go_orientacoes`,`criado_em`,`atualizado_em`) VALUES (6601,1,5006,2006,206,'pre_natal','Retorno de pré-natal sem intercorrências.','2025-11-24','G2P1A0','24 semanas','2026-08-31','Ciclos regulares antes da gestação.','Não aplicável na gestação atual.','Nega sangramentos.','Nega hipertensão, diabetes ou trombofilias.','Cesárea prévia há 4 anos.','Sem fatores de risco para IST relatados.','Coleta em 2025 com resultado dentro da normalidade.','Não se aplica pela idade e contexto clínico.','nao','Movimentos fetais presentes e regulares.','Orientada sobre perda de líquido, sangramento, cefaleia intensa, redução de movimentos fetais e dor persistente.','110x70','67,5 kg','148 bpm','24 cm','Bom estado geral, sem edema, útero compatível com IG.','Hemograma, glicemia e sorologias de rotina do trimestre.','Gestação de baixo risco em evolução adequada.','Manter suplementação, rotina de pré-natal e reavaliação periódica.','Retornar em 4 semanas e procurar serviço se sinais de alarme.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `ortopedia_traumatologia_prontuario` (`id`,`empresa_id`,`prontuario_id`,`paciente_id`,`profissional_id`,`orto_regiao`,`orto_lateralidade`,`orto_queixa_principal`,`orto_mecanismo_trauma`,`orto_tempo_sintomas`,`orto_escala_dor`,`orto_limitacao_funcional`,`orto_trauma_recente`,`orto_neurovascular`,`orto_inspecao`,`orto_amplitude_movimento`,`orto_forca`,`orto_testes_especificos`,`orto_rx`,`orto_rm`,`orto_usg`,`orto_hipotese_diag`,`orto_classificacao_fratura`,`orto_imobilizacao`,`orto_medicacoes`,`orto_fisioterapia`,`orto_conduta`,`orto_orientacoes`,`criado_em`,`atualizado_em`) VALUES (6701,1,5007,2007,207,'Joelho','direita','Dor anterior no joelho direito ao correr e subir escadas.','Sobrecarga esportiva sem trauma de alta energia.','3 semanas',6,'Desconforto para corrida, agachamento e escadas.','nao','Sem déficit neurovascular distal.','Sem deformidades, discreto edema periarticular.','Amplitude preservada com dor terminal em flexão.','Força global preservada.','Dor à compressão patelar e teste funcional com agachamento positivo para dor.','Sem alterações ósseas agudas aparentes no contexto clínico.','Não indicada neste momento se boa resposta inicial ao tratamento conservador.','Não aplicável.','Síndrome dolorosa femoropatelar / tendinopatia por sobrecarga.',NULL,'Não indicada.','Anti-inflamatório por curto período e gelo local se necessário.','Fisioterapia com fortalecimento de cadeia cinética e controle de carga.','Tratamento conservador inicial.','Reduzir impacto, alongamentos orientados e retorno progressivo após melhora.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `cardiologia_prontuario` (`id`,`empresa_id`,`prontuario_id`,`paciente_id`,`profissional_id`,`cardio_queixa_principal`,`cardio_dor_toracica`,`cardio_dispneia`,`cardio_palpitacoes`,`cardio_sincope`,`cardio_hipertensao`,`cardio_diabetes`,`cardio_tabagismo`,`cardio_hist_familiar`,`cardio_pa`,`cardio_fc`,`cardio_imc`,`cardio_exame_fisico`,`cardio_ecg`,`cardio_eco`,`cardio_teste_ergometrico`,`cardio_laboratoriais`,`cardio_hipotese_diag`,`cardio_risco_cv`,`cardio_medicacoes`,`cardio_metas`,`cardio_conduta`,`cardio_orientacoes`,`criado_em`,`atualizado_em`) VALUES (6801,1,5008,2008,208,'Palpitações e dispneia aos médios esforços.','nao','aos_medios_esforcos','sim','nao','sim','nao','cessado','Irmão com infarto agudo do miocárdio aos 54 anos.','146x88',84,'28.40','Bulhas normofonéticas em 2 tempos, sem sopros evidentes, sem edema periférico.','ECG solicitado para avaliação de ritmo e possíveis alterações de sobrecarga.','Ecocardiograma solicitado para avaliação estrutural.','Teste ergométrico programado conforme estratificação clínica.','Perfil lipídico e glicemia de jejum solicitados.','Hipertensão arterial sistêmica com palpitações em investigação; risco cardiovascular aumentado.','alto','Anlodipino 5mg/dia mantido; considerar ajuste após MAPA/Holter.','PA < 130x80 mmHg, LDL conforme estratificação e perda ponderal progressiva.','Estratificação completa com ECG, eco, Holter e controle pressórico.','Reduzir sódio, manter atividade física orientada e registrar episódios de palpitação.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `oftalmologia_prontuario` (`id`,`empresa_id`,`prontuario_id`,`paciente_id`,`profissional_id`,`oftalmo_queixa_principal`,`oftalmo_lateralidade`,`oftalmo_inicio`,`oftalmo_dor_ocular`,`oftalmo_trauma`,`oftalmo_cirurgias_previas`,`oftalmo_comorbidades`,`oftalmo_av_sc_od`,`oftalmo_av_sc_oe`,`oftalmo_av_cc_od`,`oftalmo_av_cc_oe`,`oftalmo_tonometria`,`oftalmo_biomicroscopia`,`oftalmo_fundo_olho`,`oftalmo_refracao`,`oftalmo_hipotese_diag`,`oftalmo_exames_complementares`,`oftalmo_prescricao`,`oftalmo_conduta`,`oftalmo_orientacoes`,`criado_em`,`atualizado_em`) VALUES (6901,1,5009,2009,209,'Baixa visual progressiva e cansaço visual.','ou','Evolução gradual nos últimos meses.','nao','nao','Nega cirurgias oculares prévias.','Histórico familiar de glaucoma materno.','20/60','20/50','20/30','20/25','14/15 mmHg','Biomicroscopia sem sinais inflamatórios importantes; discreta opacificação cristaliniana inicial.','Papilas sem edema; retina sem alterações agudas ao exame clínico inicial.','Melhora parcial com correção óptica subjetiva.','Erro refracional associado a catarata inicial em acompanhamento.','Mapeamento de retina e paquimetria conforme seguimento.','Óculos com atualização de grau conforme refração final.','Acompanhamento periódico e ajuste óptico.','Orientado sobre sinais de piora visual súbita e necessidade de revisão regular.','2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `neurologia_prontuario` (`id`,`empresa_id`,`prontuario_id`,`paciente_id`,`profissional_id`,`neuro_queixa_principal`,`neuro_inicio_quadro`,`neuro_instalacao`,`neuro_cefaleia`,`neuro_tontura`,`neuro_fraqueza`,`neuro_parestesia`,`neuro_crises_convulsivas`,`neuro_descricao_crise`,`neuro_frequencia_crises`,`neuro_deficit_focal`,`neuro_ultimo_evento`,`neuro_antecedentes`,`neuro_estado_mental`,`neuro_pares_cranianos`,`neuro_forca_tono`,`neuro_reflexos`,`neuro_sensibilidade`,`neuro_coordenacao`,`neuro_marcha`,`neuro_sinais_meningeos`,`neuro_tc`,`neuro_rm`,`neuro_eeg`,`neuro_enmg`,`neuro_liquor`,`neuro_hipotese_diag`,`neuro_conduta`,`neuro_orientacoes`,`neuro_retorno`,`criado_em`,`atualizado_em`) VALUES (7001,1,5010,2010,210,'Cefaleia recorrente com parestesias transitórias.','Quadro com meses de evolução, mais intenso nas últimas semanas.','cronica','sim','nao','nao','sim','nao',NULL,NULL,'Nega déficit focal persistente; parestesia transitória em membro superior esquerdo.','Crise mais recente há 4 dias.','Histórico pessoal de enxaqueca; mãe com enxaqueca.','Lúcida, orientada e com linguagem preservada.','Sem alterações evidentes ao exame clínico.','Força global preservada, tônus sem alterações relevantes.','Reflexos simétricos.','Sensibilidade preservada no exame atual.','Sem dismetria ou ataxia.','Marcha preservada.','Ausentes.','Não realizada nesta etapa por ausência de sinais agudos.','RM de crânio solicitada para investigação complementar.','Não indicado neste momento.','Não indicado.','Não indicado.','Enxaqueca com aura em investigação diferencial.','Diário de cefaleia, ajuste medicamentoso e RM de crânio.','Retornar com exames e procurar urgência se déficit focal persistente, cefaleia explosiva ou rebaixamento do nível de consciência.','2026-06-12','2026-11-11 23:52:12','2026-11-11 23:52:12');
